@Test
public void noCspViolations() throws Exception {
    try (final WebClient webClient = new WebClient()) {
        final CollectingContentSecurityPolicyViolationListener cspListener =
                new CollectingContentSecurityPolicyViolationListener();
        webClient.setContentSecurityPolicyViolationListener(cspListener);

        final HtmlPage page = webClient.getPage("https://www.example.com/");
        // interact with the page
        ...

        assertEquals("[]", cspListener.getViolations().toString());
    }
}
